// Linear interpolation between the closest ranks: R's type 7, NumPy's default. `sorted` is ascending.
export const percentile = (sorted, p) => {
    if (sorted.length === 0)
        throw new Error("percentile of no samples");
    const rank = (sorted.length - 1) * p;
    const low = Math.floor(rank);
    const high = Math.ceil(rank);
    return sorted[low] + (sorted[high] - sorted[low]) * (rank - low);
};
const round = (ms) => Math.round(ms * 10) / 10;
export const summarize = (samples) => {
    const sorted = [...samples].sort((a, b) => a - b);
    return {
        n: sorted.length,
        p50: round(percentile(sorted, 0.5)),
        p95: round(percentile(sorted, 0.95)),
        min: round(sorted[0]),
        max: round(sorted.at(-1)),
    };
};
// A statistic regresses when it is more than `threshold` (a fraction) slower than the baseline and more than
// `floorMs` slower in absolute terms, so a 2 ms metric moving to 3 ms is not a regression.
export const regressions = (current, baseline, { threshold, floorMs }) => Object.entries(current).flatMap(([metric, summary]) => {
    const base = baseline[metric];
    if (base === undefined)
        return [];
    return ["p50", "p95"]
        .filter((stat) => summary[stat] > base[stat] * (1 + threshold) && summary[stat] - base[stat] > floorMs)
        .map((stat) => ({ metric, stat, baseline: base[stat], current: summary[stat] }));
});
const ms = (value) => (value >= 100 ? value.toFixed(0) : value.toFixed(1));
const change = (current, base, regressed) => {
    if (base === undefined || base === 0)
        return "new";
    const percent = ((current - base) / base) * 100;
    const text = `${percent >= 0 ? "+" : ""}${percent.toFixed(0)}%`;
    return regressed ? `**${text}**` : text;
};
export const table = (metrics, baseline, flagged) => {
    const isFlagged = (metric, stat) => flagged.some((r) => r.metric === metric && r.stat === stat);
    const header = baseline
        ? ["| Metric (ms) | n | p50 | p95 | min | max | p50 vs baseline | p95 vs baseline |", "|---|--:|--:|--:|--:|--:|--:|--:|"]
        : ["| Metric (ms) | n | p50 | p95 | min | max |", "|---|--:|--:|--:|--:|--:|"];
    const known = Object.keys(METRICS).filter((metric) => metrics[metric] !== undefined);
    const rows = [...known, ...Object.keys(metrics).filter((metric) => METRICS[metric] === undefined).sort()]
        .map((metric) => {
        const s = metrics[metric];
        const cells = [METRICS[metric] ?? metric, String(s.n), ms(s.p50), ms(s.p95), ms(s.min), ms(s.max)];
        if (baseline) {
            cells.push(change(s.p50, baseline[metric]?.p50, isFlagged(metric, "p50")));
            cells.push(change(s.p95, baseline[metric]?.p95, isFlagged(metric, "p95")));
        }
        return `| ${cells.join(" | ")} |`;
    });
    return [...header, ...rows].join("\n");
};
/** Metrics persisted when updating a target's baseline. */
export const baselineMetrics = (previous, metrics, origins) => ({
    ...Object.fromEntries(Object.entries(previous ?? {}).map(([metric, value]) => [metric,
        origins?.previous === undefined ? value : { ...value, origin: value.origin ?? {
                source: origins.previous.source, commit: origins.previous.commit, machine: origins.previous.machine,
                server: origins.previous.server, n: origins.previous.n,
            } },
    ])),
    ...Object.fromEntries(Object.entries(metrics).map(([metric, { p50, p95 }]) => [metric,
        { p50, p95, ...(origins === undefined ? {} : { origin: origins.current }) },
    ])),
});
